package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
 * missing note is stored empty.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
        sheets.load(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount),
                date != null ? date : sheets.today(sheetId), note != null ? note : ""));
        record("CLAIM_ADDED", user, person, claim);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        claim.setAmount(scaled(amount));
        claim.setDate(date != null ? date : sheets.today(sheetId));
        claim.setNote(note != null ? note : "");
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        record("CLAIM_EDITED", user, person, claim);
        return claim;
    }

    /**
     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
     * gives the claim the sheet's next number; voiding clears it (the number is not given again).
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers.
        Sheet sheet = next == ClaimStatus.OPEN
                ? sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"))
                : null;
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        if (!claim.getStatus().canBecome(next)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next);
        }
        Long number = next == ClaimStatus.OPEN ? Long.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
        claim.setStatus(next);
        claim.setNumber(next == ClaimStatus.VOID ? null : number);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        record(switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        }, user, person, claim, number);
        return claim;
    }

    private void record(String event, String user, Person person, Claim claim) {
        record(event, user, person, claim, claim.getNumber());
    }

    /**
     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number
     * (or, when voided, the number it had) ends the line with number=&lt;number&gt;.
     */
    private void record(String event, String user, Person person, Claim claim, Long number) {
        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
        if (number != null) {
            fields.add("number=" + number);
        }
        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
    }

    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, can be opened and then settled; a DRAFT or OPEN claim can
 * be voided. SETTLED and VOID are final. Only OPEN and SETTLED claims count toward the totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to the given one. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }
}
-- A claim's status: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID instead.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A claim gets the sheet's next number when it is opened: 1, 2, ... with no gaps and never reused.
-- The sheet keeps the last number given; voiding a claim clears its number.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, claim_number);
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export interface Claim {
  id: number;
  personId: number;
  /** Always with two decimals, e.g. "2.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number given when the claim was opened; null for a draft or a voided claim. */
  number: number | null;
}

/** DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID instead. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** The status changes a claim can be asked for, as named in the store's API. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** Whether the claim counts toward claimed, due-total and every total. */
export function counts(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'SETTLED';
}

export interface ClaimFields {
  amount: string;
  date: string;
  note: string;
}

/** An amount the store accepts: 0 or more, with at most two decimals. */
export const AMOUNT = /^\d{1,10}(\.\d{1,2})?$/;

/** Whole cents of a valid amount, so sums are exact. */
export function toCents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
}

export function formatCents(cents: number): string {
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

// The claims kept on the active sheet, newest first, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly all = signal<Claim[]>([]);

  /** The claims that count toward the totals: OPEN and SETTLED ones. */
  private readonly counted = computed(() => this.all().filter(counts));

  /** Each person's claimed, in cents, by person id. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.counted()) out.set(c.personId, (out.get(c.personId) ?? 0) + toCents(c.amount));
    return out;
  });

  readonly totalCents = computed(() => this.counted().reduce((sum, c) => sum + toCents(c.amount), 0));

  /** Re-read the store; until it answers no claims are shown, so none is shown out of date. */
  async reload(): Promise<void> {
    this.all.set([]);
    try {
      this.all.set(await firstValueFrom(this.http.get<Claim[]>(`${this.sheetUrl()}/claims`, { headers: this.headers() })));
    } catch {
      this.all.set([]);
    }
  }

  async add(personId: number, fields: ClaimFields): Promise<void> {
    const added = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/people/${personId}/claims`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => [added, ...list]);
  }

  async update(id: number, fields: ClaimFields): Promise<void> {
    const saved = await firstValueFrom(
      this.http.put<Claim>(`${this.sheetUrl()}/claims/${id}`, this.body(fields), { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  /** Move a claim to its next status; the store refuses a change its status does not allow. */
  async act(id: number, action: ClaimAction): Promise<void> {
    const saved = await firstValueFrom(
      this.http.post<Claim>(`${this.sheetUrl()}/claims/${id}/${action}`, null, { headers: this.headers() }),
    );
    this.all.update((list) => list.map((c) => (c.id === saved.id ? saved : c)));
  }

  private body(fields: ClaimFields) {
    return { amount: fields.amount.trim(), date: fields.date || null, note: fields.note };
  }

  private sheetUrl(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
import { Component, computed, inject, input, linkedSignal, signal } from '@angular/core';
import { AMOUNT, Claim, ClaimAction, Claims, formatCents, toCents } from '../../core/claims';
import { Grade } from '../../core/people';
import { dueCents, Rates } from '../../core/rates';
import { Session } from '../../core/session';

// One person's claims, newest first, and the one form that adds a claim or edits an existing one.
@Component({
  selector: 'app-person-claims',
  template: `
    <form (submit)="save($event)" [attr.aria-label]="'Claim for ' + personName()">
      <label [for]="'claim-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-amount-' + personId()"
        inputmode="decimal"
        data-testid="claim-form-amount"
        [value]="amount()"
        (input)="amount.set($any($event.target).value); error.set(null)"
      />
      <label [for]="'claim-date-' + personId()">Date</label>
      <input
        [id]="'claim-date-' + personId()"
        type="date"
        data-testid="claim-form-date"
        [value]="date()"
        (input)="date.set($any($event.target).value); error.set(null)"
      />
      <label [for]="'claim-note-' + personId()">Note</label>
      <input
        [id]="'claim-note-' + personId()"
        data-testid="claim-form-note"
        [value]="note()"
        (input)="note.set($any($event.target).value); error.set(null)"
      />
      <button type="submit" data-testid="claim-form-submit">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editingId() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error(); as err) {
        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
      }
    </form>

    <ul>
      @for (c of mine(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <span data-testid="claim-number">{{ c.number }}</span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-due">{{ due(c) }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span data-testid="claim-status">{{ c.status }}</span>
          <button type="button" data-testid="claim-edit" (click)="edit(c)">
            Edit<span class="visually-hidden"> claim of {{ c.amount }} on {{ c.date }}</span>
          </button>
          @for (a of actions; track a.action) {
            <button type="button" [attr.data-testid]="'claim-' + a.action" (click)="act(c, a.action)">
              {{ a.label }}<span class="visually-hidden"> claim of {{ c.amount }} on {{ c.date }}</span>
            </button>
          }
          @if (rowError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ rowError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly claims = inject(Claims);
  private readonly session = inject(Session);
  private readonly rates = inject(Rates);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  readonly grade = input.required<Grade>();

  protected readonly mine = computed(() => this.claims.all().filter((c) => c.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly date = linkedSignal(() => this.session.today() ?? '');
  protected readonly note = signal('');
  protected readonly editingId = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** The error of the last action taken on a claim's row, if it was refused. */
  protected readonly rowError = signal<{ id: number; message: string } | null>(null);

  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  /** The claim's due at its person's grade's rate, or n/a when that grade has no rate. */
  protected due(claim: Claim): string {
    const rate = this.rates.byGrade().get(this.grade());
    return rate === undefined ? 'n/a' : formatCents(dueCents(toCents(claim.amount), rate));
  }

  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
    this.rowError.set(null);
    try {
      await this.claims.act(claim.id, action);
    } catch {
      this.rowError.set({ id: claim.id, message: `A ${claim.status} claim cannot be changed that way.` });
    }
  }

  protected edit(claim: Claim): void {
    this.rowError.set(null);
    this.editingId.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.error.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.amount.set('');
    this.date.set(this.session.today() ?? '');
    this.note.set('');
    this.error.set(null);
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    this.error.set(null);
    const fields = { amount: this.amount().trim(), date: this.date(), note: this.note() };
    if (!AMOUNT.test(fields.amount)) {
      this.error.set('Enter an amount of 0.00 or more, with at most two decimals.');
      return;
    }
    const id = this.editingId();
    try {
      if (id === null) {
        await this.claims.add(this.personId(), fields);
      } else {
        await this.claims.update(id, fields);
      }
      this.reset();
    } catch {
      this.error.set(id === null ? 'The claim could not be added.' : 'The claim could not be saved.');
    }
  }
}
